head.script:
scwin.count=0;
scwin.onpageload = function () {
    requires("uiplugin.popup");
};

scwin.onpageunload = function () {

};

scwin.trigger1_onclick = function (e) {
    scwin.count++;
    const tmpSrc = scwin.getfolderPath() + "/for_pageFrame.xml";

    var options = {

        id: scwin.count,
        type: "wframePopup",
        width: "400px",
        height: "250px",
        top: "130px",
        left: "200px",
        popupName: "PageFrame Popup",
        modal: true,
        resizable: true
    };

    $p.openPopup(tmpSrc, options);

};

